func lengthOfLongestSubstringKDistinct(s string, k int) int {
	lookup := map[byte]int{}
	start, end, maxLen, counter := 0, 0, 0, 0
	for end < len(s) {
		if lookup[s[end]] == 0 {
			counter++
		}
		lookup[s[end]]++
		end++
		for counter > k {
			if lookup[s[start]] == 1 {
				counter--
			}
			lookup[s[start]]--
			start++
		}
		if end-start > maxLen {
			maxLen = end - start
		}
	}
	return maxLen
}
